function carGearbox(car){const value=String(car.details?.gearbox||'Автомат').toLowerCase();if(/механ|\bmt\b/.test(value))return'Механика';if(/вариат|cvt/.test(value))return'Вариатор';if(/робот|dct|dsg/.test(value))return'Робот';return'Автомат'}
function carEngineType(car){const value=String(car.details?.engineType||'').toLowerCase();if(car.type.includes('electric')||/элект|electric|ev/.test(value))return'electric';if(/гибрид|hybrid|phev|hev/.test(value))return'hybrid';if(/диз|diesel/.test(value)||/\d+d\b/i.test(car.name))return'diesel';if(/газ|lpg|cng/.test(value))return'gas';return'petrol'}
