function matchesAdvanced(c){const brands=checkedValues('filterBrand'),models=checkedValues('filterModel'),gearboxes=checkedValues('filterGearbox'),engines=checkedValues('filterEngine'),bodies=checkedValues('filterBody'),drives=checkedValues('filterDrive'),conditions=checkedValues('filterCondition'),cities=checkedValues('filterCity'),brand=carBrand(c),model=carModel(c);return(!brands.length||brands.includes(brand))&&(!models.length||models.some(value=>{const[selectedBrand,selectedModel]=value.split('|||');return selectedBrand===brand&&(model===selectedModel||model.startsWith(`${selectedModel} `))}))&&inCustomOrSelectedRange(c.price,'#filterPriceFrom','#filterPriceTo','filterPrice')&&inCustomOrSelectedRange(c.year,'#filterYearFrom','#filterYearTo','filterYear')&&inCustomOrSelectedRange(carMileage(c),'#filterMileageFrom','#filterMileageTo','filterMileage')&&(!gearboxes.length||gearboxes.includes(carGearbox(c)))&&(!engines.length||engines.includes(carEngineType(c)))&&(!bodies.length||bodies.includes(carBody(c)))&&(!drives.length||drives.includes(carDrive(c)))&&(!conditions.length||conditions.some(value=>c.type.includes(value)))&&(!cities.length||cities.includes(c.city))}
