const auctionBox=document.querySelector('#auctionBox'),bidForm=document.querySelector('#bidForm');
function auctionBest(auction){return Math.max(auction.startPrice,...auction.bids.map(bid=>bid.amount))}
function auctionLeft(endsAt){const left=Math.max(0,endsAt-Date.now()),hours=Math.floor(left/3600000),minutes=Math.floor(left%3600000/60000),seconds=Math.floor(left%60000/1000);return `${String(hours).padStart(2,'0')}:${String(minutes).padStart(2,'0')}:${String(seconds).padStart(2,'0')}`}
function renderAuctionSection(){const active=cars.filter(car=>car.auction?.status==='active'&&car.auction.endsAt>Date.now());auctionGrid.innerHTML=active.map(car=>`<article class="auction-card" data-auction-car="${escapeHtml(car.id)}"><div class="auction-card-image"><img src="${car.img}" alt="${escapeHtml(car.name)}"><span>⚡ Аукцион</span><b data-auction-countdown="${car.auction.endsAt}">${auctionLeft(car.auction.endsAt)}</b></div><div class="auction-card-body"><h3>${escapeHtml(car.name)}</h3><div class="auction-card-price"><span>Лучшая ставка</span><strong>${money(auctionBest(car.auction))}</strong></div><div class="auction-card-meta"><span>${car.year} · ${car.km}</span><span>${car.auction.bids.length} предложений</span></div><button type="button">Участвовать в торгах →</button></div></article>`).join('');auctionGrid.style.display=active.length?'grid':'none';auctionEmpty.style.display=active.length?'none':'flex'}
auctionGrid.addEventListener('click',event=>{const card=event.target.closest('[data-auction-car]');if(!card)return;const car=cars.find(item=>String(item.id)===card.dataset.auctionCar);if(car){openDetail(car);renderAuction(car)}});
function persistAuctionCar(car){const own=JSON.parse(localStorage.getItem('vkluche-listings')||'[]'),index=own.findIndex(item=>String(item.id)===String(car.id));if(index>=0){own[index]=car;localStorage.setItem('vkluche-listings',JSON.stringify(own))}const overrides=JSON.parse(localStorage.getItem('vkluche-auction-overrides')||'{}');overrides[car.id]={auction:car.auction,price:car.price,badge:car.badge};localStorage.setItem('vkluche-auction-overrides',JSON.stringify(overrides))}
function renderAuction(car){
  const auction=car.auction;document.querySelector('#mobilePrimaryAction').textContent=auction?'Сделать предложение':'Позвонить продавцу';document.querySelector('#startAuction').style.display=auction?'none':'block';auctionBox.style.display=auction?'block':'none';detail.classList.toggle('auction-active',Boolean(auction));document.querySelector('.finance-note').style.display=auction?'none':'block';
  if(!auction)return;
  if(auction.status==='active'&&Date.now()>=auction.endsAt){auction.status='awaiting_seller';persistAuctionCar(car)}
  const best=auctionBest(auction),active=auction.status==='active';document.querySelector('#detailPrice').textContent=money(best);document.querySelector('#auctionBest').textContent=money(best);document.querySelector('#auctionBidCount').textContent=auction.bids.length;document.querySelector('#auctionTimer').textContent=active?auctionLeft(auction.endsAt):auction.status==='winner_selected'?'Победитель выбран':'Торги завершены';document.querySelector('#bidAmount').min=best+auction.bidStep;document.querySelector('#bidAmount').placeholder=new Intl.NumberFormat('ru-RU').format(best+auction.bidStep);bidForm.style.display=active?'grid':'none';
  const bids=[...auction.bids].sort((a,b)=>b.amount-a.amount);document.querySelector('#auctionBids').innerHTML=bids.length?bids.map(bid=>`<div class="auction-bid ${auction.winnerId===bid.id?'winner':''}"><span><b>${escapeHtml(bid.buyer)}</b><small>${bid.rating} ★ · ${escapeHtml(bid.comment||'Без комментария')}</small></span><strong>${money(bid.amount)}</strong>${auction.status!=='winner_selected'?`<button type="button" data-winner="${escapeHtml(bid.id)}">Выбрать</button>`:' '}</div>`).join(''):'<p class="no-bids">Пока нет предложений</p>';
}
bidForm.addEventListener('submit',event=>{event.preventDefault();if(!currentCar?.auction)return;if(window.vklucheAuth&&!window.vklucheAuth.require(()=>{document.querySelector('#bidAmount').focus();toast('Теперь можно сделать предложение')}))return;const auction=currentCar.auction,amount=+document.querySelector('#bidAmount').value,best=auctionBest(auction);if(auction.status!=='active'||Date.now()>=auction.endsAt){auction.status='awaiting_seller';renderAuction(currentCar);renderAuctionSection();return toast('Торги уже завершены')}if(amount<best+auction.bidStep)return toast(`Минимальная ставка — ${money(best+auction.bidStep)}`);const authUser=window.vklucheAuth?.getUser(),buyer=authUser?.user_metadata?.name||authUser?.email?.split('@')[0]||'Покупатель ВКЛЮЧЕ';auction.bids.push({id:`bid-${Date.now()}`,userId:authUser?.id,buyer,amount,comment:document.querySelector('#bidComment').value.trim(),rating:5,createdAt:Date.now()});if(auction.autoExtend&&auction.endsAt-Date.now()<5*60*1000)auction.endsAt+=5*60*1000;currentCar.price=amount;bidForm.reset();persistAuctionCar(currentCar);renderAuction(currentCar);render();renderAuctionSection();toast('Предложение принято')});
document.querySelector('#auctionBids').addEventListener('click',event=>{const button=event.target.closest('[data-winner]');if(!button||!currentCar?.auction)return;const bid=currentCar.auction.bids.find(item=>item.id===button.dataset.winner);currentCar.auction.status='winner_selected';currentCar.auction.winnerId=bid.id;currentCar.auction.winner=bid;currentCar.price=bid.amount;currentCar.badge='Победитель выбран';persistAuctionCar(currentCar);renderAuction(currentCar);render();renderAuctionSection();toast(`${bid.buyer} выбран победителем`)});
setInterval(()=>{if(currentCar?.auction&&detail.classList.contains('open'))renderAuction(currentCar);let expired=false;document.querySelectorAll('[data-auction-countdown]').forEach(timer=>{timer.textContent=auctionLeft(+timer.dataset.auctionCountdown);if(+timer.dataset.auctionCountdown<=Date.now())expired=true});if(expired)renderAuctionSection()},1000);
const photoInput=document.querySelector('#photoInput'),photoUpload=document.querySelector('#photoUpload'),preview=document.querySelector('#uploadPreview');function readPhotos(files){[...files].slice(0,10-uploadedPhotos.length).forEach(file=>{if(!file.type.startsWith('image/'))return;const reader=new FileReader();reader.onload=()=>{uploadedPhotos.push(reader.result);renderUploads()};reader.readAsDataURL(file)})}function renderUploads(){preview.innerHTML=uploadedPhotos.map((src,i)=>`<div><img src="${src}" alt="Фото автомобиля"><button type="button" data-remove-photo="${i}">×</button></div>`).join('')}photoInput.addEventListener('change',()=>readPhotos(photoInput.files));preview.addEventListener('click',e=>{const b=e.target.closest('[data-remove-photo]');if(b){uploadedPhotos.splice(+b.dataset.removePhoto,1);renderUploads()}});['dragenter','dragover'].forEach(n=>photoUpload.addEventListener(n,e=>{e.preventDefault();photoUpload.classList.add('drag')}));['dragleave','drop'].forEach(n=>photoUpload.addEventListener(n,e=>{e.preventDefault();photoUpload.classList.remove('drag')}));photoUpload.addEventListener('drop',e=>readPhotos(e.dataTransfer.files));document.querySelector('[name="price"]').addEventListener('input',e=>document.querySelector('#priceHint').textContent=e.target.value?`Покупатель увидит: ${money(+e.target.value)}`:'Укажите стоимость автомобиля');
const documentInput=document.querySelector('#documentInput'),documentPreview=document.querySelector('#documentPreview');function renderDocuments(){documentPreview.innerHTML=uploadedDocuments.map((document,index)=>`<div><span>📎</span><b>${escapeHtml(document.name)}</b><small>${Math.ceil(document.size/1024)} КБ</small><button type="button" data-remove-document="${index}" aria-label="Удалить">×</button></div>`).join('')}documentInput.addEventListener('change',()=>{const files=[...documentInput.files].slice(0,3-uploadedDocuments.length),currentSize=uploadedDocuments.reduce((sum,item)=>sum+item.size,0);files.forEach(file=>{if(currentSize+files.reduce((sum,item)=>sum+item.size,0)>4*1024*1024)return toast('Общий размер документов не должен превышать 4 МБ');const reader=new FileReader();reader.onload=()=>{uploadedDocuments.push({name:file.name,size:file.size,type:file.type,url:reader.result});renderDocuments()};reader.readAsDataURL(file)});documentInput.value=''});documentPreview.addEventListener('click',event=>{const button=event.target.closest('[data-remove-document]');if(!button)return;uploadedDocuments.splice(+button.dataset.removeDocument,1);renderDocuments()});
