document.body.insertAdjacentHTML('beforeend','<div class="modal auction-start-modal" id="auctionStartModal" role="dialog" aria-modal="true" aria-labelledby="auctionStartTitle"><div class="modal-backdrop" data-auction-start-close></div><div class="modal-card auction-start-card"><button class="modal-close" type="button" data-auction-start-close aria-label="Закрыть">×</button><span class="eyebrow blue">ЗАПУСК ТОРГОВ</span><h2 id="auctionStartTitle">Выставить автомобиль на аукцион</h2><p id="auctionStartCar"></p><form id="auctionStartForm"><div class="form-grid"><label>Стартовая цена, ₽ *<input name="startPrice" type="number" min="1" required></label><label>Резервная цена, ₽<input name="reservePrice" type="number" min="0" placeholder="Минимальная цена продажи"></label><label>Продолжительность<select name="duration"><option value="2">2 часа</option><option value="6">6 часов</option><option value="12">12 часов</option><option value="24" selected>24 часа</option><option value="48">48 часов</option></select></label><label>Минимальный шаг<select name="bidStep"><option value="5000">5 000 ₽</option><option value="10000" selected>10 000 ₽</option><option value="25000">25 000 ₽</option><option value="50000">50 000 ₽</option></select></label></div><label class="auction-check"><input name="autoExtend" type="checkbox" checked> Продлевать торги на 5 минут при поздней ставке</label><button class="primary-btn" type="submit">Запустить аукцион</button></form></div></div>');
let currentCar=null,currentPhoto=0,currentPhotos=[];const detail=document.querySelector('#carDetail');
function openDetail(car){currentCar=car;currentPhotos=[car.img,...extraPhotos];currentPhoto=0;const d=car.details||{},seller=d.seller||'Авто Эксперт',documents=d.documents||[];document.querySelector('#detailTitle').textContent=car.name;document.querySelector('#detailPrice').textContent=money(car.price);document.querySelector('#mobilePrice').innerHTML=`${car.name}<br>${money(car.price)}`;document.querySelector('#monthlyPrice').textContent=money(Math.round(car.price/60));document.querySelector('#detailDate').textContent=`Объявление · ${car.date} · ${car.city}`;document.querySelector('#detailSpecs').innerHTML=[['Год выпуска',car.year],['Пробег',car.km],['Тип двигателя',engineTypeLabels[carEngineType(car)]],['Двигатель',car.engine],['Коробка',d.gearbox||'Автомат'],['Привод',d.drive||(car.type.includes('suv')?'Полный':'Передний')],['Кузов',d.body||(car.type.includes('suv')?'Кроссовер':'Седан')],['Цвет',d.color||'Чёрный'],['Владельцев',d.owners||'1 владелец']].map(x=>`<div class="spec"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');document.querySelector('#detailDescription').textContent=d.description||`Автомобиль в отличном состоянии. Бережная эксплуатация, своевременное обслуживание и полный комплект документов.\n\nОригинальный пробег, без серьёзных ДТП. Два комплекта ключей. Возможна проверка в любом выбранном вами сервисе. Торг после осмотра.`;document.querySelector('.seller b').textContent=seller;document.querySelector('#locationSellerName').textContent=seller;document.querySelector('#locationSellerAvatar').textContent=seller.charAt(0).toUpperCase();document.querySelector('#showPhone').textContent='Показать телефон';document.querySelector('#mapCity').textContent=car.city;const documentsSection=document.querySelector('#documentsSection');documentsSection.style.display=documents.length?'block':'none';document.querySelector('#detailDocuments').innerHTML=documents.map(document=>`<a class="vehicle-document" href="${document.url}" ${String(document.url).startsWith('data:')?`download="${escapeHtml(document.name)}"`:'target="_blank" rel="noopener"'}><span>${document.type?.includes('pdf')?'PDF':'ФАЙЛ'}</span><span><b>${escapeHtml(document.name)}</b><small>Открыть документ →</small></span></a>`).join('');updateGallery();updateDetailFav();detail.classList.add('open');document.body.style.overflow='hidden'}
const auctionStartModal=document.querySelector('#auctionStartModal'),auctionStartForm=document.querySelector('#auctionStartForm');
function closeAuctionStart(){auctionStartModal.classList.remove('open');document.body.style.overflow=detail.classList.contains('open')?'hidden':''}
document.querySelector('#startAuction').addEventListener('click',()=>{if(!currentCar||currentCar.auction)return;if(window.vklucheAuth&&!window.vklucheAuth.require(()=>document.querySelector('#startAuction').click()))return;document.querySelector('#auctionStartCar').textContent=currentCar.name;auctionStartForm.elements.startPrice.value=currentCar.price;auctionStartModal.classList.add('open')});
document.querySelectorAll('[data-auction-start-close]').forEach(button=>button.addEventListener('click',closeAuctionStart));
auctionStartForm.addEventListener('submit',event=>{event.preventDefault();if(!currentCar)return;const values=new FormData(auctionStartForm),startPrice=+values.get('startPrice'),reservePrice=+values.get('reservePrice')||0;if(reservePrice&&reservePrice<startPrice)return toast('Резервная цена должна быть не ниже стартовой');currentCar.auction={status:'active',startPrice,reservePrice,bidStep:+values.get('bidStep'),endsAt:Date.now()+(+values.get('duration')*60*60*1000),autoExtend:values.get('autoExtend')==='on',bids:[]};currentCar.price=startPrice;currentCar.badge='Аукцион';persistAuctionCar(currentCar);closeAuctionStart();renderAuction(currentCar);renderAuctionSection();render();toast('Аукцион запущен')});
function updateGallery(){document.querySelector('#detailImage').src=currentPhotos[currentPhoto];document.querySelector('#detailImage').alt=currentCar.name;document.querySelector('#photoCount').textContent=`${currentPhoto+1} / ${currentPhotos.length}`;document.querySelector('#galleryThumbs').innerHTML=currentPhotos.map((p,i)=>`<button class="${i===currentPhoto?'active':''}" data-photo="${i}"><img src="${p}" alt="Фото ${i+1}"></button>`).join('')}
function closeDetail(){detail.classList.remove('open');document.body.style.overflow=''}
document.querySelectorAll('[data-detail-close]').forEach(b=>b.addEventListener('click',closeDetail));document.querySelector('#prevPhoto').addEventListener('click',()=>{currentPhoto=(currentPhoto-1+currentPhotos.length)%currentPhotos.length;updateGallery()});document.querySelector('#nextPhoto').addEventListener('click',()=>{currentPhoto=(currentPhoto+1)%currentPhotos.length;updateGallery()});document.querySelector('#galleryThumbs').addEventListener('click',e=>{const b=e.target.closest('[data-photo]');if(b){currentPhoto=+b.dataset.photo;updateGallery()}});
function updateDetailFav(){const on=saved.has(currentCar.id),b=document.querySelector('#detailFav');b.textContent=on?'♥ В избранном':'♡ Добавить в избранное';b.classList.toggle('saved',on);const mobile=document.querySelector('#mobileFavorite');mobile.textContent=on?'♥':'♡';mobile.classList.toggle('saved',on)}
document.querySelector('#detailFav').addEventListener('click',()=>{saved.has(currentCar.id)?saved.delete(currentCar.id):saved.add(currentCar.id);localStorage.setItem('vkluche-favs',JSON.stringify([...saved]));updateDetailFav();render()});document.querySelector('#showPhone').addEventListener('click',e=>e.target.textContent=currentCar.details?.phone||'+7 927 555-18-42');document.querySelector('#sendMessage').addEventListener('click',()=>toast('Чат с продавцом открыт'));document.querySelector('#shareCar').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);toast('Ссылка скопирована')}catch{toast('Ссылка готова к отправке')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDetail();closeWizard()}if(detail.classList.contains('open')&&e.key==='ArrowRight')document.querySelector('#nextPhoto').click();if(detail.classList.contains('open')&&e.key==='ArrowLeft')document.querySelector('#prevPhoto').click()});
const sellerProfileModal=document.querySelector('#sellerProfileModal');function openSellerProfile(){if(!currentCar)return;const seller=currentCar.details?.seller||'Авто Эксперт',initial=seller.charAt(0).toUpperCase();document.querySelector('#sellerProfileTitle').textContent=seller;document.querySelector('#sellerProfileAvatar').textContent=initial;document.querySelector('#sellerListingCount').textContent=cars.filter(car=>(car.details?.seller||'Авто Эксперт')===seller).length;sellerProfileModal.classList.add('open')}function closeSellerProfile(){sellerProfileModal.classList.remove('open')}document.querySelector('#sellerProfileLink').addEventListener('click',openSellerProfile);document.querySelectorAll('[data-seller-profile-close]').forEach(button=>button.addEventListener('click',closeSellerProfile));document.querySelector('#profileMessage').addEventListener('click',()=>{closeSellerProfile();toast('Чат с продавцом открыт')});document.addEventListener('keydown',event=>{if(event.key==='Escape')closeSellerProfile()});
document.querySelector('#mobileFavorite').addEventListener('click',()=>document.querySelector('#detailFav').click());
document.querySelector('#mobileMessage').addEventListener('click',()=>document.querySelector('#sendMessage').click());
document.querySelector('#mobilePrimaryAction').addEventListener('click',event=>{if(currentCar?.auction){document.querySelector('#auctionBox').scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('#bidAmount').focus()}else{event.currentTarget.textContent=currentCar?.details?.phone||'+7 927 555-18-42'}});
document.querySelectorAll('#navLinks a,#navLinks button').forEach(item=>item.addEventListener('click',()=>document.querySelector('#navLinks').classList.remove('open')));
async function loadRemoteListings(){const client=window.vklucheAuth?.getClient();if(!client)return;const{data,error}=await client.from('listings').select('data').eq('active',true).order('updated_at',{ascending:false});if(error){console.warn(`Каталог Supabase пока недоступен: ${error.message}`);return}for(let i=cars.length-1;i>=0;i--)if(cars[i].source==='automatic-feed')cars.splice(i,1);cars.unshift(...data.map(row=>row.data));fillFilterCities();render();renderAuctionSection()}
fillFilterCities();render();renderAuctionSection();loadRemoteListings();
